INSERT INTO item VALUES (1198,'Illusion','Staff',NULL,'No','Strong illusion','13','65,000 gp',NULL,'Craft Staff, disguise self, major image, mirror image, persistent image, project image, rainbow pattern',NULL,NULL,'\n      <div topic=\"Illusion\" level=\"8\"><p><b>Illusion:</b> This staff is made from ebony or other dark wood and carved into an intricately twisted, fluted, or spiral shape. It allows use of the following spells:</p><ul>\n <li> <i>Disguise self</i> (1 charge)</li>\n <li> <i>Mirror image</i> (1 charge)</li>\n <li> <i>Major image</i> (1 charge)</li>\n <li> <i>Rainbow pattern</i> (2 charges)</li>\n <li> <i>Persistent image</i> (2 charges)</li>\n <li> <i>Mislead</i> (3 charges)</li>\n</ul><p>Strong illusion; CL 13th; Craft Staff, <i>disguise self</i>,  <i>major image</i>,  <i>mirror image</i>,  <i>persistent image</i>,  <i>project image</i>,  <i>rainbow pattern</i>; Price 65,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIV');
INSERT INTO item VALUES (1199,'Illumination','Staff',NULL,'No','Strong evocation','15','48,250 gp',NULL,'Craft Staff, dancing lights, daylight, flare, sunburst',NULL,NULL,'\n      <div topic=\"Illumination\" level=\"8\"><p><b>Illumination:</b> This staff is usually sheathed in silver and decorated with sunbursts. It allows use of the following spells:</p><ul>\n <li> <i>Dancing lights</i> (1 charge)</li>\n <li> <i>Flare</i> (1 charge)</li>\n <li> <i>Daylight</i> (2 charges)</li>\n <li> <i>Sunburst</i> (3 charges)</li>\n</ul><p>Strong evocation; CL 15th; Craft Staff, <i>dancing lights</i>,  <i>daylight</i>,  <i>flare</i>,  <i>sunburst</i>; Price 48,250 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIV');
INSERT INTO item VALUES (1200,'Life','Staff',NULL,'No','Moderate conjuration','11','155,750 gp',NULL,'Craft Staff, heal, resurrection',NULL,NULL,'\n      <div topic=\"Life\" level=\"8\"><p><b>Life:</b> Made of thick oak shod in gold, this staff allows use of the following spells:</p><ul>\n <li> <i>Heal</i> (1 charge)</li>\n <li> <i>Raise dead</i> (5 charges)</li>\n</ul><p>Moderate conjuration; CL 11th; Craft Staff, <i>heal</i>,  <i>resurrection</i>; Price 155,750 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIV');
INSERT INTO item VALUES (1201,'Necromancy','Staff',NULL,'No','Strong necromancy','13','65,000 gp',NULL,'Craft Staff, cause fear, circle of death, enervation, ghoul touch, halt undead, waves of fatigue',NULL,NULL,'\n      <div topic=\"Necromancy\" level=\"8\"><p><b>Necromancy:</b> This staff is made from ebony or other dark wood and carved with the images of bones and skulls. It allows use of the following spells:</p><ul>\n <li> <i>Cause fear</i> (1 charge)</li>\n <li> <i>Ghoul touch</i> (1 charge)</li>\n <li> <i>Halt undead</i> (1 charge)</li>\n <li> <i>Enervation</i> (2 charges)</li>\n <li> <i>Waves of fatigue</i> (2 charges)</li>\n <li> <i>Circle of death</i> (3 charges)</li>\n</ul><p>Strong necromancy; CL 13th; Craft Staff, <i>cause fear</i>,  <i>circle of death</i>,  <i>enervation</i>,  <i>ghoul touch</i>,  <i>halt undead</i>,  <i>waves of fatigue</i>; Price 65,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIV');
INSERT INTO item VALUES (1202,'Passage','Staff',NULL,'No','Strong varied','17','170,500 gp',NULL,'Craft Staff, astral projection, dimension door, greater teleport, passwall, phase door',NULL,NULL,'\n      <div topic=\"Passage\" level=\"8\"><p><b>Passage:</b> This potent item allows use of the following spells:</p><ul>\n <li> <i>Dimension door</i> (1 charge)</li>\n <li> <i>Passwall</i> (1 charge)</li>\n <li> <i>Phase door</i> (2 charges)</li>\n <li> <i>Greater teleport</i> (2 charges)</li>\n <li> <i>Astral projection</i> (2 charges)</li>\n</ul><p>Strong varied; CL 17th; Craft Staff, <i>astral projection</i>,  <i>dimension door</i>,  <i>greater teleport</i>,  <i>passwall</i>,  <i>phase door</i>; Price 170,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIV');
INSERT INTO item VALUES (1203,'Power','Staff',NULL,'No','Strong varied','15','211,000 gp',NULL,'Craft Staff, Craft Magic Arms and Armor, magic missile, heightened ray of enfeeblement, continual flame, levitate, heightened fireball, heightened lightning bolt, cone of cold, hold monster, wall of force, globe of invulnerability',NULL,NULL,'\n      <div topic=\"Power\" level=\"8\"><p><b>Power:</b> The <i>staff of power</i> is a very potent magic item, with offensive and defensive abilities. It is usually topped with a glistening gem, its shaft straight and smooth. It has the following powers:</p><ul>\n <li> <i>Magic missile</i> (1 charge)</li>\n <li> <i>Ray of enfeeblement</i> (heightened to 5th level) (1 charge)</li>\n <li> <i>Continual flame</i> (1 charge)</li>\n <li> <i>Levitate</i> (1 charge)</li>\n <li> <i>Lightning bolt</i> (heightened to 5th level) (1 charge)</li>\n <li> <i>Fireball</i> (heightened to 5th level) (1 charge)</li>\n <li> <i>Cone of cold</i> (2 charges)</li>\n <li> <i>Hold monster</i> (2 charges)</li>\n <li> <i>Wall of force</i> (in a 10-ft. -diameter hemisphere around the caster only) (2 charges)</li>\n <li> <i>Globe of invulnerability</i> (2 charges)</li>\n</ul><p>The wielder of a <i>staff of power</i> gains a +2 luck bonus to AC and saving throws. The staff is also a <i>+2 quarterstaff</i>,  and its wielder may use it to smite opponents. If 1 charge is expended (as a free action), the staff causes double damage (x3 on a critical hit) for 1 round.</p><p>A <i>staff of power</i> can be used for a retributive strike, requiring it to be broken by its wielder. (If this breaking of the staff is purposeful and declared by the wielder, it can be performed as a standard action that does not require the wielder to make a Strength check.) All charges currently in the staff are instantly released in a 30-foot radius. All within 2 squares of the broken staff take points of damage equal to 8 x the number of charges in the staff, those 3 or 4 squares away take 6 x the number of charges in damage, and those 5 or 6 squares distant take 4 x the number of charges in damage. All those affected can make DC 17 Reflex saves to reduce the damage by half.</p><p>The character breaking the staff has a 50% chance of traveling to another plane of existence, but if he does not, the explosive release of spell energy destroys him. Only certain items, including the <i>staff of the magi</i> and the <i>staff of power</i>,  are capable of being used for a retributive strike.</p><p>After all charges are used up from the staff, it remains a <i>+2 quarterstaff</i>. (Once empty of charges, it cannot be used for a retributive strike.)</p><p>Strong varied; CL 15th; Craft Staff, Craft Magic Arms and Armor, <i>magic missile</i>,  heightened <i>ray of enfeeblement</i>,  <i>continual flame</i>,  <i>levitate</i>,  heightened <i>fireball</i>,  heightened <i>lightning bolt</i>,  <i>cone of cold</i>,  <i>hold monster</i>,  <i>wall of force</i>,  <i>globe of invulnerability</i>; Price 211,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIV');
INSERT INTO item VALUES (1204,'Size Alteration','Staff',NULL,'No','Faint conjuration','8','29,000 gp',NULL,'Craft Staff, Enlarge person, mass enlarge person, reduce person, mass reduce person, shrink item',NULL,NULL,'\n      <div topic=\"Size Alteration\" level=\"8\"><p><b>Size Alteration:</b> Stout and sturdy, this staff of dark wood allows use of the following spells:</p><ul>\n <li> <i>Enlarge person</i> (1 charge)</li>\n <li> <i>Reduce person</i> (1 charge)</li>\n <li> <i>Shrink item</i> (1 charge)</li>\n <li> <i>Enlarge person</i>,  <i>mass</i> (1 charge)</li>\n <li> <i>Reduce person</i>,  <i>mass</i> (1 charge)</li>\n</ul><p>Faint conjuration; CL 8th; Craft Staff, <i>Enlarge person</i>,  <i>mass enlarge person</i>,  <i>reduce person</i>,  <i>mass reduce person</i>,  <i>shrink item</i>; Price 29,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIV');
INSERT INTO item VALUES (1205,'Swarming Insects','Staff',NULL,'No','Moderate conjuration','9','24,750 gp',NULL,'Craft Staff, insect plague, summon swarm',NULL,NULL,'\n      <div topic=\"Swarming Insects\" level=\"8\"><p><b>Swarming Insects:</b> Made of twisted dark wood with dark spots resembling crawling insects (which occasionally seem to move), this staff allows use of the following spells:</p><ul>\n <li> <i>Summon swarm</i> (1 charge)</li>\n <li> <i>Insect plague</i> (3 charges)</li>\n</ul><p>Moderate conjuration; CL 9th; Craft Staff, <i>insect plague</i>,  <i>summon swarm</i>; Price 24,750 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIV');
INSERT INTO item VALUES (1206,'Transmutation','Staff',NULL,'No','Strong transmutation','13','65,000 gp',NULL,'Craft Staff, alter self, baleful polymorph, blink, disintegrate, expeditious retreat, polymorph',NULL,NULL,'\n      <div topic=\"Transmutation\" level=\"8\"><p><b>Transmutation:</b> This staff is generally carved from or decorated with petrified wood and allows use of the following spells:</p><ul>\n <li> <i>Expeditious retreat</i> (1 charge)</li>\n <li> <i>Alter self</i> (1 charge)</li>\n <li> <i>Blink</i> (1 charge)</li>\n <li> <i>Polymorph</i> (2 charges)</li>\n <li> <i>Baleful polymorph</i> (2 charges)</li>\n <li> <i>Disintegrate</i> (3 charges)</li>\n</ul><p>Strong transmutation; CL 13th; Craft Staff, <i>alter self</i>,  <i>baleful polymorph</i>,  <i>blink</i>,  <i>disintegrate</i>,  <i>expeditious retreat</i>,  <i>polymorph</i>; Price 65,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIV');
INSERT INTO item VALUES (1207,'Woodlands','Staff',NULL,'No','Moderate varied','13','101,250 gp',NULL,'Craft Staff, Craft Magic Arms and Armor, animate plants, barkskin, charm animal, pass without trace, speak with animals, summon nature\'s ally VI, wall of thorns',NULL,NULL,'\n      <div topic=\"Woodlands\" level=\"8\"><p><b>Woodlands:</b> Appearing to have grown naturally into its shape, this oak, ash, or yew staff allows use of the following spells:</p><ul>\n <li> <i>Charm animal</i> (1 charge)</li>\n <li> <i>Speak with animals</i> (1 charge)</li>\n <li> <i>Barkskin</i> (2 charges)</li>\n <li> <i>Wall of thorns</i> (3 charges)</li>\n <li> <i>Summon nature\'s ally VI</i> (3 charges)</li>\n <li> <i>Animate plants</i> (4 charges)</li>\n</ul><p>The staff may be used as a weapon, functioning as a <i>+2 quarterstaff</i>. The <i>staff of the woodlands</i> also allows its wielder to <i>pass without trace</i> at will, with no charge cost. These two attributes continue to function after all the charges are expended.</p><p>Moderate varied; CL 13th; Craft Staff, Craft Magic Arms and Armor, <i>animate plants</i>,  <i>barkskin</i>,  <i>charm animal</i>,  <i>pass without trace</i>,  <i>speak with animals</i>,  <i>summon nature\'s ally VI</i>,  <i>wall of thorns</i>; Price 101,250 gp.</p><p/>\n</div>\n    ','SRD 3.5 MagicItemsIV');
