INSERT INTO item VALUES (1292,'Amulet of Mighty Fists +1','Wondrous',NULL,'No','Faint evocation','5','6,000 gp',NULL,'Craft Wondrous Item, greater magic fang, creator\'s caster level must be at least three times the amulet\'s bonus',NULL,NULL,'\n      <div topic=\"Amulet of Mighty Fists\" level=\"8\"><p><b>Amulet of Mighty Fists:</b> This amulet grants an enhancement bonus of +1 to +5 on attack and damage rolls with unarmed attacks and natural weapons.</p><p>Faint evocation; CL 5th; Craft Wondrous Item, <i>greater magic fang</i>, creator\'s caster level must be at least three times the amulet\'s bonus; Price 6,000 gp (+1), 24,000 gp (+2), 54,000 gp (+3), 96,000 gp (+4), 150,000 gp (+5).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
