INSERT INTO item VALUES (1297,'Amulet of Natural Armor +1','Wondrous',NULL,'No','Faint transmutation','5','2,000 gp',NULL,'Craft Wondrous Item, barkskin, creator\'s caster level must be at least three times the amulet\'s bonus',NULL,NULL,'\n      <div topic=\"Amulet of Natural Armor\" level=\"8\"><p><b>Amulet of Natural Armor:</b> This amulet, usually crafted from bone or beast scales, toughens the wearer\'s body and flesh, giving him an enhancement bonus to his natural armor bonus of from +1 to +5, depending on the kind of amulet.</p><p>Faint transmutation; CL 5th; Craft Wondrous Item, <i>barkskin</i>,  creator\'s caster level must be at least three times the amulet\'s bonus; Price 2,000 gp (+1), 8,000 gp (+2), 18,000 gp (+3), 32,000 gp (+4), or 50,000 gp (+5).</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
